STORY = [('paquita', 'Hombre, Arturo.', 'Well, Arturo.', [(351, 'Hombre, Arturo.')], ''), ('paquita', 'Buenas noches, Paquita.', 'Good evening, Paquita.', [(351, 'Buenas noches, Paquita.')], ''), ('paquita', '¿Qué tal?', 'How are you?', [(352, '¿Qué tal?')], ''), ('paquita', 'Muy bien, ¿y tú, a dar una vuelta?', 'Very good, and you, going for a walk?', [(352, 'Muy bien, ¿y tú, a dar una vuelta?')], ''), ('paquita', 'Sí, aquí, de visita.', 'Yes, here, visiting.', [(353, 'Sí, aquí, de visita.')], ''), ('paquita', 'Eso está bien, ¿qué vas a hacer?', 'That is good, what are you going to do?', [(353, 'Eso está bien, ¿qué vas a hacer?')], ''), ('paquita', 'Pues ponme un gin-tonic y unos torreznos.', 'Well, give me a gin and tonic and some pork rinds.', [(354, 'Pues ponme un gin-tonic'), (354, 'y unos torreznos.')], ''), ('paquita', 'Muy bien, de Larios, ¿verdad?', 'Very good, Larios brand, right?', [(355, 'Muy bien, de Larios, ¿verdad?')], ''), ('paquita', 'Como siempre.', 'As always.', [(356, 'Como siempre.')], ''), ('paquita', 'Tú tan castiza.', 'You so traditional.', [(356, 'Tú tan castiza.')], ''), ('paquita', 'A la copa... convido yo.', 'The drink... is on me.', [(357, 'A la copa... convido yo.')], ''), ('paquita', 'Hombre, Pepe.', 'Well, Pepe.', [(358, 'Hombre, Pepe.')], ''), ('paquita', '¿Qué pasa, Paqui?', 'What is up, Paqui?', [(359, '¿Qué pasa, Paqui?')], ''), ('paquita', '¿Ya no quieres nada con los pobres?', 'You do not want anything to do with the poor anymore?', [(359, '¿Ya no quieres nada con los pobres?')], ''), ('paquita', 'Claro, como ahora juegas en primera división.', 'Of course, since now you play in the first division.', [(360, 'Claro, como ahora juegas'), (360, 'en primera división.')], ''), ('paquita', 'Ya me han dicho, ya, que estás entrenando un equipo de fútbol.', 'They have already told me, yeah, that you are training a soccer team.', [(361, 'Ya me han dicho, ya, que estás'), (361, 'entrenando un equipo de fútbol.')], ''), ('paquita', 'Sí, aquí seguimos, en el pueblo.', 'Yes, here we are still, in the town.', [(362, 'Sí, aquí seguimos, en el pueblo.')], ''), ('paquita', 'Pero no se te olvida, ¿eh?', 'But you do not forget, huh?', [(363, 'Pero no se te olvida, ¿eh?')], ''), ('paquita', 'Ay, si las piedras de la plaza hablaran...', 'Oh, if the stones of the square could speak...', [(364, 'Ay, si las piedras de la plaza'), (364, 'hablaran...')], ''), ('paquita', 'Pues por mucho que juegue en primera división,', 'Well, as much as I play in the first division,', [(365, 'Pues por mucho que juegue'), (365, 'en primera división,')], ''), ('paquita', 'todavía hay... partidos amistosos.', 'there are still... friendly matches.', [(366, 'todavía hay... partidos amistosos.')], ''), ('paquita', 'Yo estoy dispuesto a jugar un partido amistoso', 'I am willing to play a friendly match', [(367, 'Yo estoy dispuesto a jugar'), (367, 'un partido amistoso')], ''), ('paquita', 'con prórroga y todo.', 'with extra time and everything.', [(368, 'con prórroga y todo.')], ''), ('paquita', 'Que te caes.', 'You are falling.', [(370, 'Que te caes.')], ''), ('paquita', 'Métete más.', 'Get further in.', [(371, 'Métete más.')], ''), ('paquita', 'No llego.', 'I cannot reach.', [(371, 'No llego.')], ''), ('paquita', 'No puedo. No, no. Ponte así.', 'I cannot. No, no. Get like this.', [(372, 'No puedo. No, no. Ponte así.')], ''), ('paquita', 'Cuidado con las medias, que son caras.', 'Careful with the stockings, they are expensive.', [(373, 'Cuidado con las medias,'), (374, 'que son caras.')], ''), ('paquita', 'Calla.', 'Be quiet.', [(374, 'Calla.')], ''), ('paquita', 'Aquí.', 'Here.', [(375, 'Aquí.')], '')]

